def huber_loss(self, pred, label, delta=1.0):
        residual = torch.abs(pred - label)
        condition = residual < delta
        loss = torch.where(
            condition,
            0.5 * residual ** 2,
            delta * residual - 0.5 * delta ** 2
        )
        return torch.mean(loss)

    def pairwise_ranking_loss(self, pred, label):
        """Pairwise hinge loss encouraging correct ranking (sampled)."""
        N = pred.shape[0]
        if N <= 1:
            return torch.tensor(0.0).to(self.device)
        # Sample random pairs to avoid O(N^2)
        k = min(100, N * (N - 1) // 2)
        # generate random indices
        idx1 = torch.randint(0, N, (k,), device=self.device)
        idx2 = torch.randint(0, N, (k,), device=self.device)
        # ensure idx1 != idx2 (but small probability)
        diff = pred[idx1] - pred[idx2]
        label_diff = label[idx1] - label[idx2]
        mask = torch.abs(label_diff) > 1e-6
        concordant = torch.sign(diff) == torch.sign(label_diff)
        loss = torch.where(mask & (~concordant), torch.relu(1.0 - diff * label_diff), torch.tensor(0.0).to(self.device))
        return loss.sum() / (mask.sum() + 1e-8)

    def loss_fn(self, pred, label):
        mask = ~torch.isnan(label)
        pred_m = pred[mask]
        label_m = label[mask]
        if len(pred_m) == 0:
            return torch.tensor(0.0).to(self.device)
        reg_loss = self.huber_loss(pred_m, label_m)
        rank_loss = self.pairwise_ranking_loss(pred_m, label_m)
        total_loss = self.loss_alpha * reg_loss + (1 - self.loss_alpha) * rank_loss
        return total_loss

    def metric_fn(self, pred, label):
        mask = torch.isfinite(label)
        if self.metric in ("", "loss"):
            return -self.loss_fn(pred[mask], label[mask])
        raise ValueError("unknown metric `%s`" % self.metric)
